  {"begriff":"Ziel-ROAS","kurz":"Gebotsstrategie, bei der Google auf einen festgelegten Umsatz pro eingesetztem Werbe-Euro optimiert.","siehe":["Smart Bidding","ROAS (Return on Ad Spend)"],"modul":8},
  {"begriff":"Zielgruppe","kurz":"Die Gruppe von Menschen, die ein Unternehmen mit seinem Angebot und seiner Kommunikation erreichen will.","mehr":"Eine Persona macht die Zielgruppe konkret und greifbar.","siehe":["Persona"],"modul":1}
